import sys, json, random, itertools; sys.path.insert(0,'/workspace/tmp_tests')
import ref
from harness import ok

POOL = ['n%d.test.'%i for i in range(8)] + ['*.test.','*.sub.test.','sub.test.','x.sub.test.','y.x.sub.test.',
        'test.','out.example.','far.away.','*.', 'up.test.']

def gen(rng):
    zones=[]
    origins = rng.sample(['test.','sub.test.','x.sub.test.','other.','out.example.'], rng.randint(1,4))
    for org in origins:
        recs=[]
        cands=[n for n in POOL if ref.below(n.lower(), org.lower())]
        for _ in range(rng.randint(0,8)):
            if not cands: break
            o=rng.choice(cands)
            style=rng.random()
            if style<0.45:
                recs.append({'owner':o,'type':'CNAME','data':rng.choice(POOL)})
            elif style<0.7:
                recs.append({'owner':o,'type':'A','data':'10.%d.%d.%d'%(rng.randrange(256),rng.randrange(256),rng.randrange(1,255))})
            elif style<0.85:
                recs.append({'owner':o,'type':'TXT','data':rng.choice(['t','','a'*10])})
            else:
                recs.append({'owner':o,'type':'AAAA','data':rng.choice(['::1','2001:db8::%x'%rng.randrange(1,99),'fe80::1'])})
        # sanitize: CNAME exclusivity, unique targets, no CNAME at origin
        byown={}
        for r in recs: byown.setdefault(r['owner'].lower(),[]).append(r)
        final=[]
        for own, rs in byown.items():
            if own == org.lower():
                rs=[r for r in rs if r['type']!='CNAME']
            if any(r['type']=='CNAME' for r in rs):
                final.append({'owner':rs[0]['owner'],'type':'CNAME','data':rs[0]['data']})
            else:
                seen=set()
                for r in rs:
                    k=(r['owner'].lower(),r['type'],r['data'])
                    if k in seen: continue
                    seen.add(k); final.append(r)
        zones.append({'origin':org,'records':final})
    pids = rng.sample(['p','q','r','s','t','u','v','w'], rng.randint(1,6))
    profiles=[{'id':i,'max_aliases':rng.choice([0,1,2,3,5,64]),'cname':rng.choice(['follow','stop']),
               'wildcard':rng.choice(['rfc','off','one-label'])} for i in pids]
    nq=rng.randint(0,9)
    queries=[{'id':'q%d'%i,'name':rng.choice(POOL+['N3.TEST.','*.X.Sub.TEST.']),'type':rng.choice(['A','CNAME','TXT','AAAA']),'cost':rng.randint(1,25)} for i in range(nq)]
    obs=[]
    if queries:
        for i in range(rng.randint(0,5)):
            if rng.random()<0.35:
                res={'status':'timeout'}
            else:
                ans=[]
                for _ in range(rng.randint(0,4)):
                    t=rng.choice(['A','CNAME','TXT','AAAA'])
                    d={'A':'10.%d.1.1'%rng.randrange(256),'CNAME':rng.choice(POOL),'TXT':'t','AAAA':'::1'}[t]
                    ans.append({'owner':rng.choice(POOL),'type':t,'data':d})
                res={'status':'response','rcode':rng.choice(['NOERROR','NXDOMAIN','SERVFAIL','REFUSED']),'answer':ans}
            obs.append({'id':'o%d'%i,'query':rng.choice(queries)['id'],'profile':rng.choice(profiles)['id'],'result':res})
    return {'zones':zones,'profiles':profiles,'queries':queries,'observations':obs}

seed=int(sys.argv[1]); rng=random.Random(seed)
fails=0
for trial in range(700):
    doc=gen(rng)
    try:
        actual=ok(doc)
    except AssertionError as e:
        print('REJECTED trial',trial,str(e)[:200]); print(json.dumps(doc)[:1500]); fails+=1; break
    expected=ref.analyze(doc)
    if actual['runs']!=expected['runs']:
        print('RUNS MISMATCH',trial)
        for a,b in zip(actual['runs'],expected['runs']):
            if a!=b: print('sub:',json.dumps(a)); print('ref:',json.dumps(b))
        print(json.dumps(doc)[:2000]); fails+=1; break
    if actual['audits']!=expected['audits']:
        print('AUDIT MISMATCH',trial,json.dumps(actual['audits']),json.dumps(expected['audits'])); fails+=1; break
    da,de=actual['diagnostic'],expected['diagnostic']
    if da['equivalence']!=de['equivalence'] or (da['cost'],da['count'])!=(de['cost'],de['count']):
        print('DIAG MISMATCH',trial,da,de); print(json.dumps(doc)[:2000]); fails+=1; break
    pids=sorted(p['id'] for p in doc['profiles']); qids=sorted(q['id'] for q in doc['queries'])
    m={(r['query'],r['profile']):(r['rcode'],frozenset((x['owner'],x['type'],x['data']) for x in r['answer'])) for r in expected['runs']}
    for a,b in itertools.combinations(pids,2):
        if any(m[(q,a)]!=m[(q,b)] for q in qids):
            assert any(m[(q,a)]!=m[(q,b)] for q in da['basis']),(trial,a,b)
print('fuzz2 seed',seed,'failures',fails)
PYEOF
